using Maestro.Quest.Interaction;
using Newtonsoft.Json.Linq;
using static Maestro.Quest.Programs.CapabilitySchema;
namespace Maestro.Quest.Programs {
    internal static class PhysicsInputFacts {
        static ProgramDataType Type()=>OutputType(Object(new JObject{
            ["state"]=Choice("inactive","ready","pending","unavailable"),["ready"]=new JObject{["type"]="boolean"},["reason"]=Text(null,128),
            ["dependencyCount"]=Number(0,66,true),["dependencies"]=List(Text(null,64),0,4),["momentumHeld"]=new JObject{["type"]="boolean"},["interrupted"]=new JObject{["type"]="boolean"}}));
        internal static BehaviourCatalog.FactDefinition Fact()=>new("object.physics.inputs",Type(),"Object physics inputs",
            "Read current native gravity/obstacle/water input ownership for a loaded solid/bouncy object and its connected physics group. Physical links share preparation and solver readiness; area membership alone does not create a physics group. Fixed, held, carried, paused and unavailable owners report inactive. A free member waiting for its ground, another member or a joint reports unavailable or pending. In an already running world, an owned free body may acquire dormant local ground while remaining stopped; it never borrows the scan when its policy requires virtual ground. Preparation does not admit gravity, impulses or settlement: current ground columns, complete local inputs and connected joints must all be ready. pending means bounded native preparation. After fixing unavailable inputs, pause and then start physics to retry. ready also rechecks current local geometry; it is not a clear path, completed throw or regional-streaming guarantee. dependencyCount counts the current required input identities; dependencies lists only the first four stable IDs. momentumHeld is transient velocity retained only during uninterrupted preparation: Pause, grab, animation, teleport, source edits and workspace retirement discard it. interrupted means a completed native step reached unavailable geometry or left its selected ground boundary. Unavailable geometry holds its free dynamic contact/constraint group while exact inputs prepare. A ground-boundary exit restores that group's last accepted poses and holds it; independent bodies keep running. Neither interruption replays old velocity. Grab, animation or teleport cancels the changed actor and its current physical connection group; merely touching another interrupted body does not grant control of it or resume it. Continuing native guard contacts are rechecked without requiring a fresh collision-enter callback. When preparation finishes, pause then start physics, or grab the object, to resume from rest. This is an explicit interruption, not a successful throw or authored contact. Reads never acquire native objects, start physics, save or change velocity. Retirement keeps each active dynamic actor and its local collision, ground, water and physical-connection dependencies, including sleeping and pending bodies. Unused unrelated areas may retire. Explicit Start still prepares all saved participants, and unavailable resident imports retain the conservative global stop.",
            Object(new JObject{["target"]=Text("^[a-zA-Z0-9_-]{1,64}$",64)}),new JObject{["target"]="example-object"},
            (context,args)=>context.Editor?.Find((string)args["target"])?.GetComponent<RigidRoomItem>() is RigidRoomItem rigid?ProgramValue.Literal(rigid.ObservePhysicsInputs(),Type()):null);
    }
}
